INSERT INTO `bot_documents` (`id`, `title`, `source_type`, `content`, `active`, `created_at`, `updated_at`) VALUES
(1, 'Chính sách giao hàng', 'POLICY', 'Chính sách giao hàng của Pharmacy Online:\n- Đơn hàng sẽ được xử lý trong vòng 24 giờ sau khi đặt hàng thành công.\n- Thời gian giao hàng: 2-5 ngày làm việc tùy khu vực.\n- Phí ship: miễn phí cho đơn hàng trên 500.000đ, dưới 500.000đ phí ship 30.000đ.\n- Khu vực nội thành: giao trong 1-2 ngày.\n- Khu vực ngoại thành / tỉnh: giao trong 3-5 ngày.\n- Đơn hàng có thể theo dõi qua mã đơn trên hệ thống.', 1, '2026-03-24 21:43:22', '2026-03-24 21:43:22'),
(2, 'Chính sách đổi trả', 'POLICY', 'Chính sách đổi trả hàng:\n- Thời hạn đổi trả: 7 ngày kể từ ngày nhận hàng.\n- Điều kiện: sản phẩm còn nguyên seal, chưa sử dụng, còn hóa đơn.\n- Thuốc đã mở seal không được đổi trả (theo quy định dược phẩm).\n- Trường hợp hàng lỗi do nhà sản xuất: đổi trả miễn phí.\n- Liên hệ hotline 1900-xxxx hoặc chat với dược sĩ để yêu cầu đổi trả.', 1, '2026-03-24 21:43:22', '2026-03-24 21:43:22'),
(3, 'Chính sách thanh toán', 'POLICY', 'Phương thức thanh toán hỗ trợ:\n- Thanh toán khi nhận hàng (COD).\n- Chuyển khoản ngân hàng qua VietQR.\n- Thanh toán online.\n- Đối với khách hàng B2B: hỗ trợ công nợ theo thỏa thuận.\n- Hóa đơn điện tử được gửi qua email sau khi đơn hàng hoàn thành.', 1, '2026-03-24 21:43:22', '2026-03-24 21:43:22'),
(4, 'Hướng dẫn đặt hàng', 'GUIDE', 'Cách đặt hàng trên Pharmacy Online:\nBước 1: Đăng nhập tài khoản.\nBước 2: Tìm sản phẩm bằng thanh tìm kiếm hoặc duyệt theo danh mục.\nBước 3: Thêm sản phẩm vào giỏ hàng, chọn số lượng.\nBước 4: Vào giỏ hàng, kiểm tra và chọn Thanh toán.\nBước 5: Nhập địa chỉ giao hàng, chọn phương thức thanh toán.\nBước 6: Xác nhận đơn hàng.\nBước 7: Theo dõi đơn hàng qua mục Đơn hàng của tôi.', 1, '2026-03-24 21:43:22', '2026-03-24 21:43:22'),
(5, 'Hướng dẫn tra cứu đơn hàng', 'GUIDE', 'Cách tra cứu đơn hàng:\n- Đăng nhập vào hệ thống.\n- Vào mục \"Đơn hàng\" trên menu.\n- Xem danh sách đơn hàng với trạng thái: PENDING, CONFIRMED, SHIPPING, DELIVERED, CANCELLED.\n- Nhấn vào mã đơn để xem chi tiết.\n- Có thể hủy đơn nếu trạng thái còn PENDING.', 1, '2026-03-24 21:43:22', '2026-03-24 21:43:22'),
(6, 'Giờ làm việc và liên hệ', 'FAQ', 'Thông tin liên hệ Pharmacy Online:\n- Giờ mở cửa: 8:00 - 21:00 hàng ngày (kể cả Chủ Nhật).\n- Hotline: 1900-xxxx (8:00 - 20:00).\n- Email: support@pharmacy-online.vn\n- Chat trực tuyến với dược sĩ: có sẵn trên website.\n- Địa chỉ: 123 Đường ABC, Quận XYZ, TP.HCM.', 1, '2026-03-24 21:43:22', '2026-03-24 21:43:22'),
(7, 'Chính sách giao hàng', 'POLICY', 'Chính sách giao hàng của Pharmacy Online:\n- Đơn hàng sẽ được xử lý trong vòng 24 giờ sau khi đặt hàng thành công.\n- Thời gian giao hàng: 2-5 ngày làm việc tùy khu vực.\n- Phí ship: miễn phí cho đơn hàng trên 500.000đ, dưới 500.000đ phí ship 30.000đ.\n- Khu vực nội thành: giao trong 1-2 ngày.\n- Khu vực ngoại thành / tỉnh: giao trong 3-5 ngày.\n- Đơn hàng có thể theo dõi qua mã đơn trên hệ thống.', 1, '2026-03-25 21:48:44', '2026-03-25 21:48:44'),
(8, 'Chính sách đổi trả', 'POLICY', 'Chính sách đổi trả hàng:\n- Thời hạn đổi trả: 7 ngày kể từ ngày nhận hàng.\n- Điều kiện: sản phẩm còn nguyên seal, chưa sử dụng, còn hóa đơn.\n- Thuốc đã mở seal không được đổi trả (theo quy định dược phẩm).\n- Trường hợp hàng lỗi do nhà sản xuất: đổi trả miễn phí.\n- Liên hệ hotline 1900-xxxx hoặc chat với dược sĩ để yêu cầu đổi trả.', 1, '2026-03-25 21:48:44', '2026-03-25 21:48:44'),
(9, 'Chính sách thanh toán', 'POLICY', 'Phương thức thanh toán hỗ trợ:\n- Thanh toán khi nhận hàng (COD).\n- Chuyển khoản ngân hàng qua VietQR.\n- Thanh toán online.\n- Đối với khách hàng B2B: hỗ trợ công nợ theo thỏa thuận.\n- Hóa đơn điện tử được gửi qua email sau khi đơn hàng hoàn thành.', 1, '2026-03-25 21:48:44', '2026-03-25 21:48:44'),
(10, 'Hướng dẫn đặt hàng', 'GUIDE', 'Cách đặt hàng trên Pharmacy Online:\nBước 1: Đăng nhập tài khoản.\nBước 2: Tìm sản phẩm bằng thanh tìm kiếm hoặc duyệt theo danh mục.\nBước 3: Thêm sản phẩm vào giỏ hàng, chọn số lượng.\nBước 4: Vào giỏ hàng, kiểm tra và chọn Thanh toán.\nBước 5: Nhập địa chỉ giao hàng, chọn phương thức thanh toán.\nBước 6: Xác nhận đơn hàng.\nBước 7: Theo dõi đơn hàng qua mục Đơn hàng của tôi.', 1, '2026-03-25 21:48:44', '2026-03-25 21:48:44'),
(11, 'Hướng dẫn tra cứu đơn hàng', 'GUIDE', 'Cách tra cứu đơn hàng:\n- Đăng nhập vào hệ thống.\n- Vào mục \"Đơn hàng\" trên menu.\n- Xem danh sách đơn hàng với trạng thái: PENDING, CONFIRMED, SHIPPING, DELIVERED, CANCELLED.\n- Nhấn vào mã đơn để xem chi tiết.\n- Có thể hủy đơn nếu trạng thái còn PENDING.', 1, '2026-03-25 21:48:44', '2026-03-25 21:48:44'),
(12, 'Giờ làm việc và liên hệ', 'FAQ', 'Thông tin liên hệ Pharmacy Online:\n- Giờ mở cửa: 8:00 - 21:00 hàng ngày (kể cả Chủ Nhật).\n- Hotline: 1900-xxxx (8:00 - 20:00).\n- Email: support@pharmacy-online.vn\n- Chat trực tuyến với dược sĩ: có sẵn trên website.\n- Địa chỉ: 123 Đường ABC, Quận XYZ, TP.HCM.', 1, '2026-03-25 21:48:44', '2026-03-25 21:48:44'),
(13, 'Giới thiệu website', 'FAQ', 'Giới thiệu về Pharmacy Online:\nPharmacy Online là hệ thống nhà thuốc trực tuyến B2B, chuyên cung cấp dược phẩm cho các nhà thuốc và cơ sở y tế.\nHệ thống hỗ trợ:\n- Đặt hàng trực tuyến 24/7\n- Tra cứu sản phẩm theo tên, nhóm bệnh, hoạt chất\n- Theo dõi đơn hàng real-time\n- Chat hỗ trợ với dược sĩ\n- Quản lý công nợ B2B\n- Chương trình loyalty cho khách hàng thân thiết\nWebsite được xây dựng trên nền tảng công nghệ hiện đại, đảm bảo trải nghiệm mua hàng nhanh chóng và an toàn.', 0, '2026-03-25 21:48:44', '2026-04-27 13:55:29'),
(14, 'Chương trình khách hàng thân thiết', 'POLICY', 'Chương trình loyalty Pharmacy Online:\n- Tích điểm: mỗi 10.000đ mua hàng = 1 điểm loyalty.\n- Quy đổi: 100 điểm = giảm 50.000đ cho đơn hàng tiếp theo.\n- Hạng thành viên: Đồng (0-99 điểm), Bạc (100-499 điểm), Vàng (500+ điểm).\n- Ưu đãi hạng Vàng: miễn phí ship, ưu tiên xử lý đơn, coupon riêng hàng tháng.\n- Điểm loyalty có hiệu lực 12 tháng kể từ ngày tích.\n- Xem điểm và hạng: đăng nhập > Tài khoản > Loyalty.', 0, '2026-03-25 21:48:44', '2026-04-27 13:55:29'),
(15, 'Chinh sach giao hang', 'POLICY', 'Chinh sach giao hang cua Pharmacy Online:\n- Don hang duoc xu ly sau khi he thong xac nhan thanh cong.\n- Thoi gian giao hang phu thuoc khu vuc nhan hang va trang thai xu ly don.\n- Phi van chuyen duoc hien thi ro tai buoc thanh toan.\n- Nguoi mua co the theo doi trang thai don trong muc Don hang.\n', 1, '2026-04-27 13:55:28', '2026-04-27 13:55:28'),
(16, 'Chinh sach doi tra', 'POLICY', 'Chinh sach doi tra:\n- Chi ho tro doi tra theo dieu kien duoc cong bo tren he thong.\n- San pham phai con nguyen tinh trang, con chung tu can thiet neu co.\n- Cac mat hang duoc phap luat hoac quy dinh duoc pham gioi han doi tra se ap dung theo quy dinh hien hanh.\n- Nguoi mua can lien he ho tro de duoc huong dan quy trinh doi tra.\n', 1, '2026-04-27 13:55:28', '2026-04-27 13:55:28'),
(17, 'Chinh sach thanh toan', 'POLICY', 'Hinh thuc thanh toan duoc ho tro:\n- Thanh toan khi nhan hang neu don hang du dieu kien.\n- Chuyen khoan ngan hang.\n- Thanh toan online neu he thong dang ho tro.\n- Hoa don va thong tin thanh toan duoc luu cung don hang de doi chieu.\n', 1, '2026-04-27 13:55:28', '2026-04-27 13:55:28'),
(18, 'Huong dan dat hang', 'GUIDE', 'Huong dan dat hang:\n- Dang nhap tai khoan.\n- Tim san pham theo ten, nhom benh, danh muc hoac hoat chat neu co du lieu.\n- Them san pham vao gio hang.\n- Kiem tra gio hang, dia chi giao hang va hinh thuc thanh toan.\n- Xac nhan don va theo doi trang thai trong muc Don hang.\n', 1, '2026-04-27 13:55:28', '2026-04-27 13:55:28'),
(19, 'Huong dan tra cuu don hang', 'GUIDE', 'Huong dan tra cuu don hang:\n- Dang nhap tai khoan da dat hang.\n- Mo muc Don hang.\n- Xem danh sach don va trang thai hien tai.\n- Mo chi tiet tung don de xem san pham, tong tien va lich su xu ly neu he thong cung cap.\n- Co the tim kiem theo ma don neu giao dien ho tro.\n', 1, '2026-04-27 13:55:28', '2026-04-27 13:55:28'),
(20, 'Gio lam viec va lien he', 'FAQ', 'Thong tin lien he:\n- Gio ho tro duoc cong bo tren website.\n- Hotline va email ho tro duoc hien thi tai khu vuc lien he.\n- Neu can tu van chuyen mon, nguoi dung duoc huong dan chat voi duoc si.\n', 1, '2026-04-27 13:55:28', '2026-04-27 13:55:28'),
(21, 'Gioi thieu he thong', 'FAQ', 'Gioi thieu Pharmacy Online:\n- He thong ho tro ban le va ban si duoc pham, thuc pham chuc nang va thiet bi y te.\n- Ho tro tim san pham, dat hang, theo doi don va chat voi duoc si.\n- Du lieu giao dich thoi gian thuc duoc tra cuu qua API he thong, khong dua vao kho tri thuc tinh.\n', 1, '2026-04-27 13:55:28', '2026-04-27 13:55:28');

