--
-- Cấu trúc bảng cho bảng `bot_faqs`
--

DROP TABLE IF EXISTS `bot_faqs`;
CREATE TABLE IF NOT EXISTS `bot_faqs` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `intent` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'MEDICINE_SEARCH, ORDER_STATUS, STORE_INFO, SIDE_EFFECTS, DOSAGE, GENERAL',
  `keywords` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Comma-separated trigger keywords',
  `question` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  `answer` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `priority` int(11) NOT NULL DEFAULT '5',
  `active` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_faq_intent` (`intent`),
  KEY `idx_faq_active` (`active`)
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Đang đổ dữ liệu cho bảng `bot_faqs`
--

INSERT INTO `bot_faqs` (`id`, `intent`, `keywords`, `question`, `answer`, `priority`, `active`, `created_at`, `updated_at`) VALUES
(1, 'STORE_INFO', 'giờ mở cửa,mấy giờ,giờ làm việc,mở cửa,đóng cửa', 'Nhà thuốc mở cửa lúc mấy giờ?', 'Nhà thuốc hoạt động từ 7:00 sáng đến 22:00 tối, tất cả các ngày trong tuần kể cả Chủ nhật và ngày lễ.', 8, 1, '2026-04-13 21:13:00', '2026-04-13 21:13:00'),
(2, 'STORE_INFO', 'địa chỉ,ở đâu,chi nhánh,cửa hàng,vị trí,bản đồ', 'Địa chỉ nhà thuốc ở đâu?', 'Nhà thuốc tọa lạc tại 123 Nguyễn Huệ, Quận 1, TP.HCM. Quý khách có thể liên hệ hotline 1900-xxxx để được hướng dẫn đường đi.', 8, 1, '2026-04-13 21:13:00', '2026-04-13 21:13:00'),
(3, 'ORDER_STATUS', 'kiểm tra đơn,tra cứu đơn,đơn hàng,tình trạng đơn,tracking', 'Làm sao kiểm tra tình trạng đơn hàng?', 'Quý khách vui lòng đăng nhập vào tài khoản và vào mục \"Đơn hàng của tôi\" để theo dõi tình trạng đơn hàng. Nếu cần hỗ trợ thêm, hãy liên hệ qua chat với dược sĩ.', 7, 1, '2026-04-13 21:13:00', '2026-04-13 21:13:00'),
(4, 'ORDER_STATUS', 'hủy đơn,cancel,không muốn mua,trả hàng', 'Tôi muốn hủy đơn hàng, làm sao?', 'Quý khách có thể hủy đơn hàng khi đơn còn ở trạng thái \"Chờ duyệt\". Nếu đơn đã được xác nhận, vui lòng liên hệ dược sĩ qua chat để được hỗ trợ hủy đơn.', 7, 1, '2026-04-13 21:13:00', '2026-04-13 21:13:00'),
(5, 'MEDICINE_SEARCH', 'thuốc giảm đau,đau đầu,hạ sốt,paracetamol,ibuprofen,nhức đầu', 'Có thuốc giảm đau nào phù hợp không?', 'Nhà thuốc có các loại thuốc giảm đau thông dụng như Paracetamol 500mg (2.000đ/viên), Ibuprofen 400mg (3.500đ/viên). Quý khách có thể xem chi tiết và đặt mua trên trang danh sách thuốc.', 6, 0, '2026-04-13 21:13:00', '2026-04-27 13:55:26'),
(6, 'MEDICINE_SEARCH', 'kháng sinh,amoxicillin,azithromycin,nhiễm khuẩn,viêm,nhiễm trùng', 'Nhà thuốc có bán thuốc kháng sinh không?', 'Có, nhà thuốc có các loại kháng sinh như Amoxicillin 500mg, Azithromycin 250mg. Lưu ý: thuốc kháng sinh cần có đơn thuốc của bác sĩ. Vui lòng liên hệ dược sĩ để được tư vấn.', 6, 1, '2026-04-13 21:13:00', '2026-04-13 21:13:00'),
(7, 'GENERAL', 'đổi trả,trả hàng,hoàn tiền,bảo hành,chính sách', 'Chính sách đổi trả hàng như thế nào?', 'Nhà thuốc hỗ trợ đổi trả trong vòng 7 ngày kể từ ngày mua nếu sản phẩm còn nguyên seal, chưa sử dụng và có hóa đơn. Thuốc đã bóc seal không được đổi trả theo quy định dược.', 5, 1, '2026-04-13 21:13:00', '2026-04-13 21:13:00'),
(8, 'GENERAL', 'thanh toán,COD,chuyển khoản,phương thức,trả tiền,bank', 'Nhà thuốc hỗ trợ những phương thức thanh toán nào?', 'Nhà thuốc hỗ trợ thanh toán bằng: tiền mặt (tại quầy hoặc COD), chuyển khoản ngân hàng, và thẻ tín dụng/ghi nợ. Đối với đơn online, quý khách có thể chọn COD hoặc chuyển khoản khi đặt hàng.', 5, 1, '2026-04-13 21:13:00', '2026-04-13 21:13:00');

