--
-- Cấu trúc bảng cho bảng `bot_query_logs`
--

DROP TABLE IF EXISTS `bot_query_logs`;
CREATE TABLE IF NOT EXISTS `bot_query_logs` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `session_id` bigint(20) DEFAULT NULL,
  `user_id` bigint(20) DEFAULT NULL,
  `message` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `detected_intent` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `route_used` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'RAG, API, GUARDRAIL, OUT_OF_SCOPE',
  `response_text` text COLLATE utf8mb4_unicode_ci,
  `response_time_ms` int(11) DEFAULT NULL,
  `blocked_by_guardrail` tinyint(1) DEFAULT '0',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_qlog_user` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=38 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Đang đổ dữ liệu cho bảng `bot_query_logs`
--

INSERT INTO `bot_query_logs` (`id`, `session_id`, `user_id`, `message`, `detected_intent`, `route_used`, `response_text`, `response_time_ms`, `blocked_by_guardrail`, `created_at`) VALUES
(1, 5, 6, 'chính sách giao hàng', 'FAQ_POLICY', 'RAG', 'Chào bạn, đây là chính sách giao hàng của Pharmacy Online:\n\n*   Đơn hàng sẽ được xử lý trong vòng 24 giờ sau khi đặt hàng thành công.\n*   Thời gian giao hàng:\n    *   Khu vực nội thành: 1-2 ngày làm việc.\n    *   Khu vực ngoại thành / tỉnh: 3-5 ngày làm việc.\n*   Phí ship:\n    *   Miễn phí cho đơn hàng trên 500.000đ.\n    *   30.000đ cho đơn hàng dưới 500.000đ.\n*   Bạn có thể theo dõi đơn hàng qua mã đơn trên hệ thống.', 2923, 0, '2026-03-25 14:54:17'),
(2, 5, 6, 'Xem đơn hàng', 'ORDER_INQUIRY', 'API', 'Bạn có 5 đơn hàng gần nhất:', 185, 0, '2026-03-25 14:54:24'),
(3, 5, 6, 'Xem đơn hàng', 'ORDER_INQUIRY', 'API', 'Bạn có 5 đơn hàng gần nhất:', 89, 0, '2026-03-25 14:54:41'),
(4, 5, 6, 'cảm cúm', 'FAQ_POLICY', 'RAG', '🤧 **Gợi ý cho cảm cúm thông thường:**\n- **Paracetamol** - Giảm sốt, đau nhức\n- **Cetirizine** - Sổ mũi, nghẹt mũi\n- **Dextromethorphan** - Ho\n- **Vitamin C** - Tăng đề kháng\n\n💧 Nhớ uống nhiều nước và nghỉ ngơi đầy đủ nhé!', 2550, 0, '2026-03-25 14:54:53'),
(5, 5, 6, 'đau', 'FAQ_POLICY', 'RAG', 'Câu hỏi: Thuốc đau đầu?\nTrả lời: 💊 **Gợi ý thuốc đau đầu thông thường:**\n- **Paracetamol 500mg** - Giảm đau, hạ sốt\n- **Ibuprofen 400mg** - Chống viêm, giảm đau\n- **Aspirin** - Giảm đau nhẹ\n\n⚠️ *Lưu ý: Nếu đau đầu kéo dài hoặc dữ dội, hãy gặp bác sĩ!*\n\nBạn muốn xem chi tiết loại thuốc nào?', 4868, 0, '2026-03-25 14:55:11'),
(6, 5, 6, 'Paracetamol 500mg', 'FAQ_POLICY', 'RAG', 'Chào bạn,\n\n**Paracetamol 500mg** được dùng để:\n- Giảm đau, hạ sốt (đối với đau đầu thông thường)\n- Giảm sốt, đau nhức (đối với cảm cúm thông thường)\n\nBạn muốn tìm hiểu thêm về sản phẩm này không?', 3501, 0, '2026-03-25 14:55:26'),
(7, 5, 6, 'thuốc đang bán', 'PRODUCT_SEARCH', 'API', 'Không tìm thấy', 92, 0, '2026-03-25 14:55:34'),
(8, 5, 6, 'chính sách giao hàng', 'FAQ_POLICY', 'RAG', 'Chào bạn, đây là chính sách giao hàng của Pharmacy Online:\n\n*   **Thời gian xử lý đơn hàng:** Đơn hàng sẽ được xử lý trong vòng 24 giờ sau khi đặt hàng thành công.\n*   **Thời gian giao hàng:**\n    *   Tổng thể: 2-5 ngày làm việc tùy khu vực.\n    *   Khu vực nội thành: giao trong 1-2 ngày.\n    *   Khu vực ngoại thành / tỉnh: giao trong 3-5 ngày.\n*   **Phí ship:**\n    *   Miễn phí cho đơn hàng trên 500.000đ.\n    *   Dưới 500.000đ phí ship là 30.000đ.\n*   **Theo dõi đơn hàng:** Bạn có thể theo dõi ', 7796, 0, '2026-03-25 14:55:47'),
(9, 5, 6, 'simple', 'FAQ_POLICY', 'RAG', 'Chào bạn, mình chưa có thông tin về \"simple\" trong ngữ cảnh này. Bạn có thể cung cấp thêm chi tiết không ạ?', 3254, 0, '2026-03-25 14:56:26'),
(10, 5, 6, 'Sữa rửa mătk', 'FAQ_POLICY', 'RAG', '🔍 Bạn có thể tìm sữa rửa mặt bằng cách:\n1. Nhập tên sữa rửa mặt bạn muốn tìm vào ô tìm kiếm trên website.\n2. Hoặc cho mình biết bạn đang', 6540, 0, '2026-03-25 14:56:42'),
(11, 5, 6, 'sữa rửa mặt simple', 'FAQ_POLICY', 'RAG', 'Chào bạn, mình chưa có thông tin về sản phẩm sữa rửa mặt Simple trong dữ liệu hiện có.\n\nBạn có muốn mình tìm kiếm thông tin về sản phẩm khác hoặc hỗ trợ về chính sách đổi trả không?', 2587, 0, '2026-03-25 14:56:57'),
(12, 5, 6, 'có', 'FAQ_POLICY', 'RAG', 'Chào bạn! Pharmacy Online có công nghệ hiện đại, đảm bảo trải nghiệm mua hàng nhanh chóng và an toàn ạ.', 5944, 0, '2026-03-25 14:57:09'),
(13, 5, 6, 'thuoc khang sinh', 'PRODUCT_SEARCH', 'API', 'Không tìm thấy', 42, 0, '2026-03-25 14:58:00'),
(14, 5, 6, 'thuốc kháng sinh', 'PRODUCT_SEARCH', 'API', 'Không tìm thấy', 30, 0, '2026-03-25 14:58:06'),
(15, 5, 6, 'amoxicillin 501mg', 'FAQ_POLICY', 'RAG', 'Chào bạn, liều lượng thuốc phụ thuộc vào từng loại thuốc và từng người bệnh.\n\nĐể được tư vấn cụ thể về liều dùng Amoxicillin 501mg,', 6378, 0, '2026-03-25 14:58:26'),
(16, 5, 6, 'uống bao nhiêu viên', 'MEDICAL_UNSAFE', 'GUARDRAIL', 'Xin lỗi, chatbot không thể tư vấn liều dùng, kê đơn hoặc đưa lời khuyên y tế cá nhân. Bạn vui lòng liên hệ dược sĩ để được hỗ trợ chính xác hơn. 💊\n\nTôi có thể giúp bạn:\n• Tra cứu đơn hàng\n• Tìm sản phẩm\n• Giải đáp chính sách', 4, 1, '2026-03-25 14:58:41'),
(17, 5, 6, 'cảm ơn', 'FAQ_POLICY', 'RAG', '😊 Không có gì! Mình rất vui được giúp bạn.\n\nNếu cần hỗ trợ thêm, bạn cứ hỏi mình nhé! Chúc bạn sức khỏe! 💪', 4049, 0, '2026-03-25 15:00:20'),
(18, 5, 6, 'thuốc đau bụng', 'PRODUCT_SEARCH', 'API', 'Không tìm thấy', 653, 0, '2026-04-13 14:17:55'),
(19, 5, 6, 'cảm', 'FAQ_POLICY', 'RAG', 'Câu hỏi: Cảm ơn\nTrả lời: 😊 Không có gì! Mình rất vui được giúp bạn.\n\nNếu cần hỗ trợ thêm, bạn cứ hỏi mình nhé! Chúc bạn sức khỏe! 💪', 3553, 0, '2026-04-13 14:18:05'),
(20, 5, 6, 'thuốc cảm', 'PRODUCT_SEARCH', 'API', 'Không tìm thấy', 31, 0, '2026-04-13 14:18:11'),
(21, 5, 6, 'cảm cúm', 'FAQ_POLICY', 'RAG', 'Câu hỏi: Thuốc cảm cúm?\nTrả lời: 🤧 **Gợi ý cho cảm cúm thông thường:**\n- **Paracetamol** - Giảm sốt, đau nhức\n- **Cetirizine** - Sổ mũi, nghẹt mũi\n- **Dextromethorphan** - Ho\n- **Vitamin C** - Tăng đề kháng\n\n💧 Nhớ uống nhiều nước và nghỉ ngơi đầy đủ nhé!', 2028, 0, '2026-04-13 14:18:20'),
(22, 5, 6, 'tiêu hóa', 'FAQ_POLICY', 'RAG', 'Câu hỏi: Thuốc đau bụng?\nTrả lời: 🏥 **Gợi ý thuốc tiêu hóa:**\n- **Buscopan** - Đau bụng co thắt\n- **Smecta** - Tiêu chảy, viêm ruột\n- **Oresol** - Bù nước khi tiêu chảy\n- **Omeprazole** - Đau dạ dày, trào ngược\n\n⚠️ Nếu đau bụng kéo dài, hãy đến gặp bác sĩ!', 1932, 0, '2026-04-13 14:18:34'),
